const lv_img_dsc_t *icons_find(const char *name)
{
    if (name == NULL || name[0] == '\0') {
        return NULL;
    }
    for (size_t i = 0; i < sizeof(ICONS) / sizeof(ICONS[0]); i++) {
        if (strcmp(ICONS[i].name, name) == 0) {
            return ICONS[i].img;
        }
    }
    return NULL;
}
